INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > IT-Sicherheit > Bedrohungsszenarien > Identitätsdiebstahl (Phishing)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann Phishing dazu führen, dass persönliche Zugangsdaten gestohlen werden?', 2, '[{"text": "Ja", "correct": true, "because": "Phishing zielt auf Zugangsdaten ab"}, {"text": "Nein", "correct": false, "because": "Das ist ein Hauptziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Phishing immer durch technische Schwachstellen in Systemen verursacht?', 2, '[{"text": "Nein", "correct": true, "because": "Phishing nutzt menschliche Schwächen aus"}, {"text": "Ja", "correct": false, "because": "Es ist Social Engineering"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss Phishing immer über E-Mails erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch SMS oder gefälschte Websites sind möglich"}, {"text": "Ja", "correct": false, "because": "Methoden sind vielfältig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können gut geschulte Nutzer Phishing-Angriffe vollständig verhindern?', 2, '[{"text": "Nein", "correct": true, "because": "Selbst geschulte Nutzer können getäuscht werden"}, {"text": "Ja", "correct": false, "because": "Täuschung bleibt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Identitätsdiebstahl durch Phishing immer sofort erkennbar?', 2, '[{"text": "Nein", "correct": true, "because": "Diebstahl kann unbemerkt bleiben"}, {"text": "Ja", "correct": false, "because": "Erkennung oft verzögert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird bei Phishing am häufigsten eingesetzt, um Identitätsdiebstahl zu ermöglichen?', 2, '[{"text": "Gefälschte E-Mails", "correct": true, "because": "Weit verbreitet und effektiv"}, {"text": "SQL-Injection", "correct": false, "because": "Technischer Angriff"}, {"text": "Brute-Force", "correct": false, "because": "Andere Technik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt Phishing primär im Kontext von Identitätsdiebstahl?', 3, '[{"text": "Erlangung von Zugangsdaten", "correct": true, "because": "Ziel ist Identitätsübernahme"}, {"text": "Systemstörung", "correct": false, "because": "Sekundäres Ziel"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Andere Bedrohung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schutzmaßnahme ist gegen Phishing am effektivsten?', 2, '[{"text": "Nutzer-Schulung", "correct": true, "because": "Erhöht Bewusstsein für Täuschungen"}, {"text": "Firewall", "correct": false, "because": "Schützt Netzwerk, nicht Nutzer"}, {"text": "Antivirus", "correct": false, "because": "Erkennt Malware, nicht Phishing"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schwäche nutzt Phishing am häufigsten aus?', 2, '[{"text": "Menschliche Gutgläubigkeit", "correct": true, "because": "Täuscht Nutzer zur Preisgabe"}, {"text": "Schwache Passwörter", "correct": false, "because": "Anderes Problem"}, {"text": "Langsame Server", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft am besten, Phishing-E-Mails zu erkennen?', 2, '[{"text": "E-Mail-Filter", "correct": true, "because": "Erkennt verdächtige Muster"}, {"text": "Texteditor", "correct": false, "because": "Kein Sicherheitswerkzeug"}, {"text": "Router", "correct": false, "because": "Netzwerkgerät"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutzt Phishing für Identitätsdiebstahl?', 4, '[{"text": "Gefälschte E-Mails", "correct": true, "because": "Täuschen Nutzer"}, {"text": "Gefälschte Websites", "correct": true, "because": "Simulieren legitime Seiten"}, {"text": "Telefonanrufe (Vishing)", "correct": true, "because": "Täuschung per Anruf"}, {"text": "Langsame Downloads", "correct": false, "because": "Kein Phishing-Mechanismus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schutzmaßnahmen helfen gegen Phishing?', 3, '[{"text": "Nutzer-Schulung", "correct": true, "because": "Erhöht Vorsicht"}, {"text": "E-Mail-Filter", "correct": true, "because": "Blockiert verdächtige Nachrichten"}, {"text": "Mehrfaktor-Authentifizierung", "correct": true, "because": "Erschwert Missbrauch"}, {"text": "Langsamere Netzwerke", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten sind typische Ziele von Identitätsdiebstahl durch Phishing?', 4, '[{"text": "Passwörter", "correct": true, "because": "Ermöglichen Zugriff"}, {"text": "Kreditkarteninformationen", "correct": true, "because": "Finanzielle Nutzung"}, {"text": "Persönliche Identifikationsdaten", "correct": true, "because": "Identitätsübernahme"}, {"text": "Öffentliche IP-Adressen", "correct": false, "because": "Weniger sensibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann Identitätsdiebstahl durch Phishing haben?', 3, '[{"text": "Finanzielle Verluste", "correct": true, "because": "Missbrauch von Konten"}, {"text": "Reputationsschaden", "correct": true, "because": "Vertrauensverlust"}, {"text": "Unbefugter Zugriff", "correct": true, "because": "Systeme kompromittiert"}, {"text": "Verbesserte Sicherheit", "correct": false, "because": "Keine positive Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien können Phishing-Angriffe abwehren?', 3, '[{"text": "Anti-Phishing-Filter", "correct": true, "because": "Erkennt verdächtige Mails"}, {"text": "Spam-Blocker", "correct": true, "because": "Reduziert Phishing-Mails"}, {"text": "MFA", "correct": true, "because": "Schützt trotz gestohlener Daten"}, {"text": "Router-Updates", "correct": false, "because": "Weniger relevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Phishing zielt auf Identitätsdiebstahl ab. b) Es erfordert immer technische Schwachstellen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Identitätsdiebstahl ja, Technik nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nutzer-Schulung hilft gegen Phishing. b) Phishing erfolgt nur über E-Mails.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schulung ja, Methoden vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) MFA kann Phishing-Schäden reduzieren. b) Identitätsdiebstahl ist immer sofort erkennbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "MFA ja, Erkennung verzögert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Gefälschte Websites sind ein Phishing-Werkzeug. b) Gut geschulte Nutzer sind immun.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Websites ja, Immunität nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Anti-Phishing-Filter erkennen verdächtige Mails. b) Phishing zielt nur auf finanzielle Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Filter ja, Ziele vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

